 public function activation(string $module,bool $active,string $password):void {$this->keyGate();$this->confirm($password);if($module==='core')throw new \RuntimeException('Shared Core tidak boleh dinyahaktifkan.');if(file_exists($this->dir.'/maintenance.lock')||file_exists($this->dir.'/blocked.lock'))throw new \RuntimeException('Recovery lock aktif.');if(!isset($this->trust['modules'][$module]))throw new \RuntimeException('Modul tidak berdaftar.');if($module==='training'){spl_autoload_register(static function($c){$prefix='EPejabat\\Modules\\Training\\';if(str_starts_with($c,$prefix)){$n=substr($c,strlen($prefix));if(preg_match('/\A[A-Za-z]+\z/',$n))require_once APP_ROOT.'/app/Modules/Training/'.$n.'.php';}});if($active&&!\EPejabat\Modules\Training\ExtendedMigrations::ready($this->p))throw new \RuntimeException('Modul penuh belum lengkap.');\EPejabat\Modules\Training\Migrations::activate($this->p,$this->u,$active);}else{if($active){$installed=Database::query($this->p,'SELECT setting_value FROM system_settings WHERE setting_key=?',['module_version.'.$module])->fetchColumn();$verified=false;foreach($this->runs() as $run)if($run['module']===$module&&$run['version']===$installed&&$run['status']==='VERIFIED_LOCAL_INSTALL'){$verified=true;foreach($run['manifest']['files'] as $file){[$pr,$rel]=explode('/',$file['file'],2);$target=($pr==='root'?APP_ROOT:$this->public).'/'.$rel;if(UpgradePackage::symlink($target)||!is_file($target)||!hash_equals($file['after_sha256'],hash_file('sha256',$target)))$verified=false;}}if(!$verified)throw new \RuntimeException('Verified installed version required.');}Database::query($this->p,'UPDATE module_registry SET status=? WHERE module_key=?',[$active?'active':'inactive',$module]);Audit::record($this->p,'core.module_activation_changed',$this->u,null,$module,'core',null,null,['active'=>$active]);}}
 public function download(string $id,string $kind):string {$this->authorize();$this->keyGate();if(!in_array($kind,['state.json','preflight.json','files-backup.zip'],true))throw new \RuntimeException('Report tidak sah.');$f=$this->directory($id).'/'.$kind;if(!is_file($f)||UpgradePackage::symlink($f))throw new \RuntimeException('Report tiada.');Audit::record($this->p,'core.upgrade_report_access',$this->u,null,$id);return $f;}
}
